export function normalizeRpgSpriteKey(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[?'`?]/g, ' ')
    .replace(/&/g, ' et ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')
}

function normalizeSkinPath(value) {
  const raw =
    String(value || '')
      .trim()
      .replaceAll('\\\\', '/')
      .replaceAll('\\', '/')

  if (!raw) {
    return ''
  }

  const spritesIndex =
    raw.toLowerCase()
      .indexOf('sprites/')

  if (spritesIndex >= 0) {
    return '/' +
      raw.slice(spritesIndex)
        .replace(/^\/+/, '')
  }

  return raw.startsWith('/')
    ? raw
    : '/' + raw
}

export function rpgMonsterSprite(
  monsterName,
  skinPath = ''
) {
  const serverSprite =
    normalizeSkinPath(skinPath)

  if (serverSprite) {
    return serverSprite
  }

  const key =
    normalizeRpgSpriteKey(monsterName)

  if (!key) {
    return ''
  }

  if (RPG_MONSTER_SPRITES[key]) {
    return RPG_MONSTER_SPRITES[key]
  }

  const candidates =
    Object.keys(RPG_MONSTER_SPRITES)
      .filter(candidate =>
        candidate.includes(key) ||
        key.includes(candidate)
      )
      .sort(
        (a, b) =>
          b.length - a.length
      )

  if (!candidates.length) {
    return ''
  }

  return RPG_MONSTER_SPRITES[
    candidates[0]
  ]
}
